// Hash utilities

import * as Environment from "./environment-utils-sdk"

// Conversion functions

export function base64ArrayBufferToBase64UrlString(ab: ArrayBuffer): string {
    return btoa(String.fromCharCode(...new Uint8Array(ab))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=*$/g, '')
}

// Hashing functions

export async function base64UrlForArrayBuffer(buffer: ArrayBuffer) {
    const subtle = Environment.isBrowser ? crypto.subtle : (await import("crypto")).subtle
    return base64ArrayBufferToBase64UrlString(await subtle.digest("SHA-256", buffer))
}

export async function base64UrlForFile(file: File) {
    return base64UrlForArrayBuffer(await file.arrayBuffer())
}

export async function base64UrlForFilePath(path: string) {
    const pipeline = Environment.isBrowser ? undefined : (await import("stream")).promises.pipeline
        if(!pipeline) {
        throw new Error("pipeline not available")
    }    
    const createHash = Environment.isBrowser ? undefined : (await import("crypto")).createHash
    if(!createHash) {
        throw new Error("createHash not available")
    }
    const fs = Environment.isBrowser ? undefined : await import("fs")
    if(!fs) {
        throw new Error("fs not available")
    }
    const readable = fs.createReadStream(path)
    const hash = createHash("sha256")
    await pipeline(readable, hash)
    return hash.digest("base64url")
}


