export const GenericMediaType =  "application/octet-stream"

export function guessMimeTypeForFile(file: File) : string | undefined {
    if(file.type) return file.type
    const extension = file.name.split('.').pop()?.toLowerCase()
    return extension ? MediaTypeByExtension.get(extension) : undefined
}

export function guessMimeTypeForExtension(extension: string) : string | undefined {
    return MediaTypeByExtension.get(extension.toLowerCase())
}