import { AVNConnect } from "./AVNConnect.js"
import * as MediaUtils from "./media-utils-sdk.js"
import * as CryptoUtils from "./crypto-utils-sdk.js"
import * as Environment from "./environment-utils-sdk"

import { Authorization } from "../../gen/avn/connect/v1/authorization_pb.js"
import { GetFileUrlRequest } from "../../gen/avn/connect/v1/avnfs_pb.js"

export const Hostname = "avnfs.com"
export const UrlPrefix = `https://${Hostname}/`

export const TypeQueryParam = "type"
export const SizeQueryParam = "size"
export const NameQueryParam = "name"

export type FileSpec = { base64url: string, sizeBytes: number, mediaType: string, fileName?: string }

// TODO: more detailed checking (TWO VERSIONS)
export function isValidUrl(url: URL) : boolean {
    if(url.hostname != Hostname) {
        return false
    }
    if(!url.pathname) {
        return false
    }
    if(!url.searchParams.get(SizeQueryParam)) {
        return false
    }
    if(!url.searchParams.get(TypeQueryParam)) {
        return false
    }
    return true
}

export function decodeUrl(url: URL) : FileSpec {
	return {
		base64url: url.pathname.substring(1),
		sizeBytes: parseInt(url.searchParams.get(SizeQueryParam)!),
		mediaType: url.searchParams.get(TypeQueryParam)!,
		fileName: url.searchParams.get(NameQueryParam) || undefined,
	}
}

export function encodeUrl(spec: FileSpec) : URL {
	const url = new URL(UrlPrefix + spec.base64url)
	url.searchParams.append(SizeQueryParam, spec.sizeBytes.toString())
	url.searchParams.append(TypeQueryParam, spec.mediaType)
	if(spec.fileName) {
		url.searchParams.append(NameQueryParam, spec.fileName)
	}
	return url
}

export function updateFilename(url: URL, name: string | undefined) : URL {
    const newUrl = new URL(url)
    newUrl.searchParams.delete(NameQueryParam)
    if(name) {
        newUrl.searchParams.append(NameQueryParam, name)
    }
	return newUrl
}

function sleep(ms: number) {
    return new Promise(resolve => setTimeout(resolve, ms));
}
  
// S3 POST operations can have a small delay before availability so this function waits until it is confirmed
async function waitUntilFileIsAvailable(Connect: AVNConnect, fileSignature: GetFileUrlRequest) {
    // Don't wait longer than 100 * 10ms = 1s because that implies the upload has failed
    let maxWaitCount = 100
    while(maxWaitCount > 0) {
        const result = await Connect.Avnfs.getFileUrl(fileSignature)
        if(result.url) {
            return
        }
        console.log(`Waiting for upload confirmation for '${fileSignature.base64url}'...`)
        await sleep(10)
        --maxWaitCount
    }
    console.warn(`Upload confirmation failed for '${fileSignature.base64url}'`)
}

export async function uploadArrayBuffer(
	buffer: ArrayBuffer, 
    Connect: AVNConnect,
	auth: Authorization,
    mediaType: string,
    fileName: string | undefined,
	progressCallback: ((event: ProgressEvent) => any) | undefined,
) : Promise<URL> {
	const base64url = await CryptoUtils.base64UrlForArrayBuffer(buffer)
    const sizeBytes = BigInt(buffer.byteLength)
    const fileSignature = new GetFileUrlRequest({ base64url, sizeBytes, mediaType, fileName })
    const getFileResponse = await Connect.Avnfs.getFileUrl(fileSignature)
    // Does file already exist?
    if(getFileResponse.url) {
        console.log(`File '${fileName || base64url}' already exists`)
        return new URL(getFileResponse.url)
	}
    console.log(`Uploading file '${fileName || base64url}'...`)    
    const uploadManifest = await Connect.Avnfs.getPostManifest({ auth, ...fileSignature })
    const formData = new FormData()
    for(let field of uploadManifest.headerFields) {
        formData.append(field.name, field.value)
    }
    formData.append("file", new Blob([buffer]))
    const downloadUrl = new URL(uploadManifest.downloadUrl)
    // XMLHttpRequest is only available in a browser context
    if(typeof XMLHttpRequest != "undefined") {
        // Promisify XMLHttpRequest (fetch doesn't easily support progress)
        return new Promise(function(resolve, reject) {
            const ajax = new XMLHttpRequest()
            ajax.open("POST", uploadManifest.uploadUrl)
            if(progressCallback) {
                ajax.upload.onprogress = progressCallback
            }
            ajax.onload = async function() {
                if (ajax.status >= 200 && ajax.status < 300) {
                    console.log(`Send complete with status ${ajax.status} for '${base64url}'`)
                    await waitUntilFileIsAvailable(Connect, fileSignature)
                    resolve(downloadUrl)
                } else {
                    reject(Error(`Upload failure (${ajax.statusText || "unknown cause"})`))
                }
            }
            ajax.onerror = function() {
                reject(Error(`Network failure (${ajax.statusText || "unknown cause"})`))
            }
            console.log(`Sending file to '${base64url}'...`)
            ajax.send(formData)
        })     
    } else {
		const res = new Response(formData)
		console.log(`Uploading '${base64url}'...`)
		const uploadResponse = await fetch(uploadManifest.uploadUrl, {
			method: "POST",
			body: await res.blob(),
		})
		if(uploadResponse.ok) {
			return downloadUrl
		} else {
			console.error(`Upload failure for '${base64url}': ${uploadResponse.statusText} (${uploadResponse.status})`, await uploadResponse.text())
			throw new Error(`Upload failure`)
		}
    }
}

export async function uploadFilePath(
	path: string, 
    Connect: AVNConnect,
	auth: Authorization,
    mediaType: string,
    fileName: string | undefined,
	progressCallback: ((event: ProgressEvent) => any) | undefined,
) : Promise<URL> {
    //TODO: create streaming version so the whole file doesn't need to be in memory
    const fs = Environment.isBrowser ? undefined : await import("fs")
    if(!fs) {
        throw new Error("fs not available")
    }
    const buffer = fs.readFileSync(path)
    return await uploadArrayBuffer(buffer, Connect, auth, mediaType, fileName, progressCallback)
}

export async function uploadFile(
	file: File, 
    Connect: AVNConnect,
	auth: Authorization,
    // Optional override
    mediaType: string | undefined,
    // Optional override
    fileName: string | undefined,
	progressCallback: ((event: ProgressEvent) => any) | undefined,
) : Promise<URL> {
	const base64url = await CryptoUtils.base64UrlForFile(file)
    const sizeBytes = BigInt(file.size)
    mediaType = mediaType || MediaUtils.guessMimeTypeForFile(file) || MediaUtils.GenericMediaType
    fileName = fileName || file.name
    // Does file already exist?
    const fileSignature = new GetFileUrlRequest({ base64url, sizeBytes, mediaType, fileName })
    const getFileResponse = await Connect.Avnfs.getFileUrl(fileSignature)
    if(getFileResponse.url) {
        console.log(`File '${fileName}' already exists`)
        return new URL(getFileResponse.url)
	}
    console.log(`Uploading file '${fileName}'...`)    
    const postManifest = await Connect.Avnfs.getPostManifest({ auth, ...fileSignature })
    const formData = new FormData()
    for(let field of postManifest.headerFields) {
        formData.append(field.name, field.value)
    }
    formData.append("file", file)
    // Promisify XMLHttpRequest (fetch doesn't easily support progress)
    return new Promise(function(resolve, reject) {
        const ajax = new XMLHttpRequest()
        ajax.open("POST", postManifest.uploadUrl)
        if(progressCallback) {
            ajax.upload.onprogress = progressCallback
        }
        ajax.onload = async function() {
            if (ajax.status >= 200 && ajax.status < 300) {
                console.log(`Send complete with status ${ajax.status} for '${base64url}'`)
                await waitUntilFileIsAvailable(Connect, fileSignature)
                resolve(new URL(postManifest.downloadUrl))
            } else {
                reject(Error(`Upload failure (${ajax.statusText || "unknown cause"})`))
            }
        }
        ajax.onerror = function() {
            reject(Error(`Network failure (${ajax.statusText || "unknown cause"})`))
        }
        console.log(`Sending file to '${base64url}'...`)
        ajax.send(formData)
    })     
    
}
